from typing import Any, Dict, List

from composio import Composio

TRIAL_ID_PATH = "/logs/trial_id"
USER_ID = "zealt-user01"


def load_trial_id() -> str:
    with open(TRIAL_ID_PATH, "r", encoding="utf-8") as handle:
        return handle.read().strip()


def normalize_channel_name(name: str) -> str:
    name = name.lower()
    name = re.sub(r"[^a-z0-9-]", "-", name)
    name = re.sub(r"-+", "-", name).strip("-")
    return name


def find_channel_id(channels: List[Dict[str, Any]], name: str) -> str | None:
    for channel in channels:
        if channel.get("name") == name:
            return channel.get("id")
    return None


def main() -> None:
    trial_id = load_trial_id()
    desired_name = f"topic-test-{trial_id}"
    normalized_name = normalize_channel_name(desired_name)

    composio = Composio()
    session = composio.tool_router.create(user_id=USER_ID, toolkits=["slack"])

    tools = session.tools()
    set_topic_tool = next(
        (
            tool
            for tool in tools
            if getattr(tool, "function", None)
            and tool.function.name == "SLACK_SET_THE_TOPIC_OF_A_CONVERSATION"
        ),
        None,
    )
    if set_topic_tool is None:
        raise RuntimeError("SLACK_SET_THE_TOPIC_OF_A_CONVERSATION tool not found")

    list_response = session.execute(
        "SLACK_FIND_CHANNELS",
        arguments={
            "query": desired_name,
            "types": "public_channel",
            "exact_match": True,
        },
    )
    if list_response.error:
        raise RuntimeError(f"Channel lookup failed: {list_response.error}")

    channels = list_response.data.get("channels", [])
    channel_id = find_channel_id(channels, desired_name)

    if channel_id is None and normalized_name != desired_name:
        fallback_response = session.execute(
            "SLACK_FIND_CHANNELS",
            arguments={
                "query": normalized_name,
                "types": "public_channel",
                "exact_match": True,
            },
